										end
	
										component:Toggle()
									end
								end))
	
								table.insert(settingConnections, component.Object.MouseEnter:Connect(function()
									bind:SetVisible(true)
								end))
	
								table.insert(settingConnections, component.Object.MouseLeave:Connect(function()
