								Url = 'http://127.0.0.1:64'..(53 + i)..'/rpc?v=1',
								Headers = {
									['Content-Type'] = 'application/json',
									Origin = 'https://discord.com'
								},
								Body = body
							})
						end)
					end)
				end
			end)
		
			task.spawn(function()
				tooltip.Text = 'Copied!'
				setclipboard('https://discord.gg/VZEQJxMSnG')
			end)
		end)
		
		settingsbutton.MouseEnter:Connect(function()
