	SearchBar = function(props, children, api)
		local component = {
			Type = 'SearchBar'
		}
		
		local function listenProperty(src, dest, prop, obj)
			dest[prop] = src[prop]
			local connection = src:GetPropertyChangedSignal(prop):Connect(function()
