			versionlabel.Size = UDim2.new(1, 0, 0, 16)
			versionlabel.Text = 'Vape '..vape.Version..' '..(
				isfile('darkvape/profiles/commit.txt') and readfile('darkvape/profiles/commit.txt'):sub(1, 6) or ''
			)..' '
			versionlabel.TextColor3 = color.Dark(uipallet.Text, 0.43)
			versionlabel.TextSize = 10
			versionlabel.TextXAlignment = Enum.TextXAlignment.Right
			versionlabel.Parent = pane
		else
			api:CreateGUIButton({
				Name = props.Name,
				Function = function()
