local function captureLightingState()
	if savedLighting then return end
	savedLighting = {
		ClockTime = lightingService.ClockTime,
		Brightness = lightingService.Brightness,
		Ambient = lightingService.Ambient,
		OutdoorAmbient = lightingService.OutdoorAmbient,
		ColorShift_Top = lightingService.ColorShift_Top,
		ColorShift_Bottom = lightingService.ColorShift_Bottom,
		FogColor = lightingService.FogColor,
		FogStart = lightingService.FogStart,
		FogEnd = lightingService.FogEnd
	}
end

local function restoreLightingState()
	if not savedLighting then return end
	for prop, val in pairs(savedLighting) do
		pcall(function()
			lightingService[prop] = val
		end)
	end
	savedLighting = nil
end

local function cleanupWeather()
	if weatherPart then
		pcall(function() weatherPart:Destroy() end)
		weatherPart = nil
	end
	if lightningFolder then
		pcall(function() lightningFolder:Destroy() end)
		lightningFolder = nil
	end
	emitterPrimary = nil
	emitterSecondary = nil
end

local lastTerrainWaterCenter = nil
local lastTerrainWaterSize = nil

local function cleanupOcean()
	if lastTerrainWaterCenter and lastTerrainWaterSize then
		pcall(function()
			workspace.Terrain:FillBlock(CFrame.new(lastTerrainWaterCenter), lastTerrainWaterSize, Enum.Material.Air)
		end)
		lastTerrainWaterCenter = nil
		lastTerrainWaterSize = nil
	end
	if oceanFolder then
		pcall(function() oceanFolder:Destroy() end)
		oceanFolder = nil
	end
	oceanSurface = nil
	oceanGlow = nil
	oceanDeep = nil
	oceanTex1 = nil
	oceanTex2 = nil
	table.clear(oceanWaves)
end

local function computeMapFloorY()
	if lplr.Character and lplr.Character:FindFirstChild('HumanoidRootPart') then
		return lplr.Character.HumanoidRootPart.Position.Y - 4
	end
	local lowest = math.huge
	pcall(function()
		local map = workspace:FindFirstChild('Map')
		if map then
			for _, part in ipairs(map:GetDescendants()) do
				if part:IsA('BasePart') and part.CanCollide and part.Position.Y > 8 and part.Position.Y < lowest then
					lowest = part.Position.Y
				end
			end
		end
	end)
	if lowest ~= math.huge then return lowest end
	return 15
end

local function fillOceanTerrainAt(cx, cz)
	pcall(function()
		local t = workspace.Terrain
		if not t then return end
		local col = OceanColor and Color3.fromHSV(OceanColor.Hue, OceanColor.Sat, OceanColor.Value) or Color3.fromRGB(12, 114, 204)
		t.WaterColor = col
		t.WaterReflectance = 0.65
		t.WaterTransparency = 0.22
		t.WaterWaveSize = 0.65
		t.WaterWaveSpeed = 18

		local newCenter = Vector3.new(math.floor(cx / 64) * 64, (baseOceanY or 0) - 6, math.floor(cz / 64) * 64)
		local newSize = Vector3.new(1800, 14, 1800)
		if lastTerrainWaterCenter and (lastTerrainWaterCenter - newCenter).Magnitude > 16 then
			t:FillBlock(CFrame.new(lastTerrainWaterCenter), lastTerrainWaterSize or newSize, Enum.Material.Air)
		end
		t:FillBlock(CFrame.new(newCenter), newSize, Enum.Material.Water)
		lastTerrainWaterCenter = newCenter
		lastTerrainWaterSize = newSize
	end)
end

local function configureOceanVoid()
	cleanupOcean()
	if not OceanVoidToggle or not OceanVoidToggle.Enabled then return end

	baseOceanY = computeMapFloorY() - (OceanDepth and OceanDepth.Value or 18)
	local col = OceanColor and Color3.fromHSV(OceanColor.Hue, OceanColor.Sat, OceanColor.Value) or Color3.fromRGB(12, 114, 204)
	local deepCol = col:Lerp(Color3.fromRGB(4, 38, 96), 0.65)

	oceanFolder = Instance.new('Folder')
	oceanFolder.Name = 'DarkVapeOceanVoid'
	oceanFolder.Parent = workspace.CurrentCamera or workspace

	local cam = workspace.CurrentCamera
	local cx = cam and cam.CFrame.Position.X or 0
	local cz = cam and cam.CFrame.Position.Z or 0
	fillOceanTerrainAt(cx, cz)

	-- Deep marine seabed floor underneath the real Terrain water so skybox doesn't bleed through
	oceanDeep = Instance.new('Part')
	oceanDeep.Name = 'OceanAbyss'
	oceanDeep.Size = Vector3.new(2048, 4, 2048)
	oceanDeep.Anchored = true
	oceanDeep.CanCollide = false
	oceanDeep.CanQuery = false
	oceanDeep.CanTouch = false
	oceanDeep.Massless = true
	oceanDeep.Material = Enum.Material.SmoothPlastic
	oceanDeep.Color = deepCol
	oceanDeep.Transparency = 0
	oceanDeep.CastShadow = false
	oceanDeep.Position = Vector3.new(cx, baseOceanY - 14, cz)
	oceanDeep.Parent = oceanFolder
	oceanSurface = oceanDeep
end

local function clearCustomObjects()
	for _, v in ipairs(newobjects) do
		pcall(function() v:Destroy() end)
	end
	if workspace.Terrain then
		for _, child in ipairs(workspace.Terrain:GetChildren()) do
			if child:IsA('Clouds') and child.Name == 'DarkVapeClouds' then
				pcall(function() child:Destroy() end)
			end
		end
	end
	for _, v in ipairs(oldobjects) do
		pcall(function()
			v.Parent = v:IsA('Clouds') and workspace.Terrain or lightingService
		end)
	end
	table.clear(newobjects)
	table.clear(oldobjects)
end

local function stashExistingLightingChild(v)
	if table.find(newobjects, v) then return end
	local mode = Theme and Theme.Value or 'Blossom Sakura Sky'
	local shouldStash = false
	if mode == 'Custom' then
		local toggle = Toggles[v.ClassName]
		shouldStash = toggle and toggle.Toggle.Enabled or false
	else
		shouldStash = apidump[v.ClassName] ~= nil
	end
	if shouldStash and v.Parent == lightingService then
		table.insert(oldobjects, v)
		pcall(function() v.Parent = nil end)
	end
end

local function getResolvedWeather()
	local w = Weather and Weather.Value or 'Match Theme'
	if w ~= 'Match Theme' then return w end
	local preset = themePresets[Theme and Theme.Value or 'Blossom Sakura Sky']
	return preset and preset.Weather or 'None'
end

local function configureWeatherEmitters()
	cleanupWeather()
	local wMode = getResolvedWeather()
	if wMode == 'None' then return end

	local cam = workspace.CurrentCamera
	if not cam then return end

	weatherPart = Instance.new('Part')
	weatherPart.Name = 'DarkVapeWeatherCanopy'
	weatherPart.Size = Vector3.new(130, 1, 130)
	weatherPart.Transparency = 1
	weatherPart.Anchored = true
	weatherPart.CanCollide = false
	weatherPart.CanQuery = false
	weatherPart.CanTouch = false
	weatherPart.Massless = true
	weatherPart.CFrame = CFrame.new(cam.CFrame.Position + Vector3.new(0, 42, 0))
	weatherPart.Parent = cam

	lightningFolder = Instance.new('Folder')
	lightningFolder.Name = 'DarkVapeLightning'
	lightningFolder.Parent = cam

	local scaleMult = (ParticleSize and ParticleSize.Value or 100) / 100
	local rateMult = (Intensity and Intensity.Value or 100) / 100
	local wind = WindSway and WindSway.Value or 8

	emitterPrimary = Instance.new('ParticleEmitter')
	emitterPrimary.EmissionDirection = Enum.NormalId.Bottom
	emitterPrimary.LockedToPart = false
	emitterPrimary.Parent = weatherPart

	if wMode == 'Rain' or wMode == 'Thunderstorm' then
		local isStorm = (wMode == 'Thunderstorm')
		emitterPrimary.Texture = 'rbxasset://textures/particles/smoke_main.dds'
		emitterPrimary.Color = ColorSequence.new(
			isStorm and Color3.fromRGB(165, 195, 240) or Color3.fromRGB(185, 215, 255),
			Color3.fromRGB(220, 238, 255)
		)
		emitterPrimary.LightEmission = 0.35
		emitterPrimary.LightInfluence = 0.2
		emitterPrimary.Size = NumberSequence.new(0.28 * scaleMult)
		emitterPrimary.Squash = NumberSequence.new(isStorm and -2.65 or -2.35)
		emitterPrimary.Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0.85),
			NumberSequenceKeypoint.new(0.15, isStorm and 0.22 or 0.32),
			NumberSequenceKeypoint.new(0.85, isStorm and 0.28 or 0.38),
			NumberSequenceKeypoint.new(1, 1)
		})
		emitterPrimary.Lifetime = NumberRange.new(0.75, 1.15)
		emitterPrimary.Speed = NumberRange.new(isStorm and 78 or 64, isStorm and 96 or 80)
		emitterPrimary.Rate = math.clamp(math.floor((isStorm and 260 or 180) * rateMult), 10, 500)
		emitterPrimary.SpreadAngle = Vector2.new(isStorm and 8 or 4, isStorm and 8 or 4)
		emitterPrimary.Acceleration = Vector3.new(wind * (isStorm and 1.8 or 0.8), -35, 0)

		-- Ground mist / splash shimmer layer
		emitterSecondary = Instance.new('ParticleEmitter')
		emitterSecondary.EmissionDirection = Enum.NormalId.Bottom
		emitterSecondary.Texture = 'rbxasset://textures/particles/sparkles_main.dds'
		emitterSecondary.Color = ColorSequence.new(Color3.fromRGB(195, 220, 255))
		emitterSecondary.LightEmission = 0.4
		emitterSecondary.Size = NumberSequence.new(0.45 * scaleMult, 0.1 * scaleMult)
		emitterSecondary.Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 1),
			NumberSequenceKeypoint.new(0.5, 0.55),
			NumberSequenceKeypoint.new(1, 1)
		})
		emitterSecondary.Lifetime = NumberRange.new(0.9, 1.4)
		emitterSecondary.Speed = NumberRange.new(42, 58)
		emitterSecondary.Rate = math.clamp(math.floor((isStorm and 95 or 55) * rateMult), 5, 250)
		emitterSecondary.SpreadAngle = Vector2.new(14, 14)
		emitterSecondary.Parent = weatherPart

	elseif wMode == 'Snow' then
		emitterPrimary.Texture = 'rbxasset://textures/particles/sparkles_main.dds'
		emitterPrimary.Color = ColorSequence.new(
			Color3.fromRGB(255, 255, 255),
			Color3.fromRGB(210, 238, 255)
		)
		emitterPrimary.LightEmission = 0.55
		emitterPrimary.LightInfluence = 0.15
		emitterPrimary.Size = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0.35 * scaleMult),
			NumberSequenceKeypoint.new(0.5, 0.58 * scaleMult),
			NumberSequenceKeypoint.new(1, 0.25 * scaleMult)
		})
		emitterPrimary.Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0.9),
			NumberSequenceKeypoint.new(0.15, 0.12),
			NumberSequenceKeypoint.new(0.85, 0.18),
			NumberSequenceKeypoint.new(1, 1)
		})
		emitterPrimary.Lifetime = NumberRange.new(3.2, 5.2)
		emitterPrimary.Speed = NumberRange.new(13, 21)
		emitterPrimary.Rate = math.clamp(math.floor(150 * rateMult), 10, 400)
		emitterPrimary.RotSpeed = NumberRange.new(-90, 90)
		emitterPrimary.Rotation = NumberRange.new(0, 360)
		emitterPrimary.SpreadAngle = Vector2.new(28, 28)
		emitterPrimary.Acceleration = Vector3.new(wind, -2.5, wind * 0.4)

	elseif wMode == 'Sakura Petals' then
		emitterPrimary.Texture = 'rbxasset://textures/particles/sparkles_main.dds'
		emitterPrimary.Color = ColorSequence.new({
			ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 198, 226)),
			ColorSequenceKeypoint.new(0.5, Color3.fromRGB(255, 142, 192)),
			ColorSequenceKeypoint.new(1, Color3.fromRGB(255, 224, 240))
		})
		emitterPrimary.LightEmission = 0.45
		emitterPrimary.LightInfluence = 0.2
		emitterPrimary.Size = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0.25 * scaleMult),
			NumberSequenceKeypoint.new(0.35, 0.56 * scaleMult),
			NumberSequenceKeypoint.new(0.8, 0.48 * scaleMult),
			NumberSequenceKeypoint.new(1, 0.18 * scaleMult)
		})
		emitterPrimary.Squash = NumberSequence.new(0.38)
		emitterPrimary.Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0.85),
			NumberSequenceKeypoint.new(0.12, 0.08),
			NumberSequenceKeypoint.new(0.85, 0.14),
			NumberSequenceKeypoint.new(1, 1)
		})
		emitterPrimary.Lifetime = NumberRange.new(3.8, 6.0)
		emitterPrimary.Speed = NumberRange.new(11, 18)
		emitterPrimary.Rate = math.clamp(math.floor(135 * rateMult), 10, 380)
		emitterPrimary.RotSpeed = NumberRange.new(-160, 160)
		emitterPrimary.Rotation = NumberRange.new(0, 360)
		emitterPrimary.SpreadAngle = Vector2.new(36, 36)
		emitterPrimary.Acceleration = Vector3.new(wind * 1.1, -1.8, wind * 0.5)

		emitterSecondary = Instance.new('ParticleEmitter')
		emitterSecondary.EmissionDirection = Enum.NormalId.Bottom
		emitterSecondary.Texture = 'rbxasset://textures/particles/sparkles_main.dds'
		emitterSecondary.Color = ColorSequence.new(Color3.fromRGB(255, 115, 175), Color3.fromRGB(255, 205, 230))
		emitterSecondary.LightEmission = 0.65
		emitterSecondary.Size = NumberSequence.new(0.36 * scaleMult)
		emitterSecondary.Squash = NumberSequence.new(0.25)
		emitterSecondary.Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0.9),
			NumberSequenceKeypoint.new(0.2, 0.15),
			NumberSequenceKeypoint.new(0.8, 0.2),
			NumberSequenceKeypoint.new(1, 1)
		})
		emitterSecondary.Lifetime = NumberRange.new(3.5, 5.5)
		emitterSecondary.Speed = NumberRange.new(9, 15)
		emitterSecondary.Rate = math.clamp(math.floor(65 * rateMult), 5, 220)
		emitterSecondary.RotSpeed = NumberRange.new(-200, 200)
		emitterSecondary.Rotation = NumberRange.new(0, 360)
		emitterSecondary.SpreadAngle = Vector2.new(42, 42)
		emitterSecondary.Acceleration = Vector3.new(wind * 0.9, -1.4, -wind * 0.4)
		emitterSecondary.Parent = weatherPart

	elseif wMode == 'Starfall' then
		emitterPrimary.Texture = 'rbxasset://textures/particles/sparkles_main.dds'
		emitterPrimary.Color = ColorSequence.new({
			ColorSequenceKeypoint.new(0, Color3.fromRGB(120, 230, 255)),
			ColorSequenceKeypoint.new(0.5, Color3.fromRGB(220, 130, 255)),
			ColorSequenceKeypoint.new(1, Color3.fromRGB(255, 190, 120))
		})
		emitterPrimary.LightEmission = 0.9
		emitterPrimary.Size = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0.15 * scaleMult),
			NumberSequenceKeypoint.new(0.5, 0.52 * scaleMult),
			NumberSequenceKeypoint.new(1, 0.1 * scaleMult)
		})
		emitterPrimary.Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0.8),
			NumberSequenceKeypoint.new(0.2, 0.05),
			NumberSequenceKeypoint.new(0.8, 0.15),
			NumberSequenceKeypoint.new(1, 1)
		})
		emitterPrimary.Lifetime = NumberRange.new(2.5, 4.2)
		emitterPrimary.Speed = NumberRange.new(14, 24)
		emitterPrimary.Rate = math.clamp(math.floor(110 * rateMult), 10, 320)
		emitterPrimary.RotSpeed = NumberRange.new(-120, 120)
		emitterPrimary.Rotation = NumberRange.new(0, 360)
		emitterPrimary.SpreadAngle = Vector2.new(35, 35)
		emitterPrimary.Acceleration = Vector3.new(wind * 0.6, -2.0, 0)
	end
end

local function spawnLightningBolt(originPos)
	if not lightningFolder then return end
	task.spawn(function()
		local boltModel = Instance.new('Model')
		boltModel.Name = 'LightningBolt'
		boltModel.Parent = lightningFolder

		local angle = math.random() * math.pi * 2
		local dist = math.random(75, 165)
		local currentPos = originPos + Vector3.new(math.cos(angle) * dist, 95, math.sin(angle) * dist)
		local segments = 10
		for i = 1, segments do
			local nextPos = currentPos + Vector3.new(math.random(-8, 8), -11, math.random(-8, 8))
			local seg = Instance.new('Part')
			seg.Anchored = true
			seg.CanCollide = false
			seg.CanQuery = false
			seg.CanTouch = false
			seg.Material = Enum.Material.Neon
			seg.Color = Color3.fromRGB(210, 235, 255)
			local len = (nextPos - currentPos).Magnitude
			seg.Size = Vector3.new(0.55, 0.55, len)
			seg.CFrame = CFrame.lookAt((currentPos + nextPos) * 0.5, nextPos)
			seg.Parent = boltModel
			currentPos = nextPos
		end
		task.wait(0.14)
		pcall(function() boltModel:Destroy() end)
	end)
end

local function applyTheme()
	if not Atmosphere or not Atmosphere.Enabled then return end
	captureLightingState()
	clearCustomObjects()

	for _, v in ipairs(lightingService:GetChildren()) do
		stashExistingLightingChild(v)
	end

	local mode = Theme and Theme.Value or 'Blossom Sakura Sky'
	if mode == 'Custom' then
		for i, v in pairs(Toggles) do
			if v.Toggle.Enabled then
				local obj = Instance.new(i)
				for i2, v2 in pairs(v.Objects) do
					pcall(function()
						if v2.Type == 'ColorSlider' then
							obj[i2] = Color3.fromHSV(v2.Hue, v2.Sat, v2.Value)
						else
							obj[i2] = apidump[i][i2] ~= 'Number' and v2.Value or tonumber(v2.Value) or 0
						end
					end)
				end
				obj.Parent = lightingService
				table.insert(newobjects, obj)
			end
		end
	else
		local preset = themePresets[mode]
		if preset then
			if preset.Lighting then
				for prop, val in pairs(preset.Lighting) do
					pcall(function() lightingService[prop] = val end)
				end
			end
			if CustomTimeToggle and CustomTimeToggle.Enabled then
				pcall(function() lightingService.ClockTime = CustomClockTime.Value end)
			end
			if preset.Sky then
				local sky = Instance.new('Sky')
				sky.Name = 'DarkVapeSky'
				for prop, val in pairs(preset.Sky) do
					pcall(function() sky[prop] = val end)
				end
				sky.Parent = lightingService
				table.insert(newobjects, sky)
			end
			if preset.Atmosphere then
				local atmo = Instance.new('Atmosphere')
				atmo.Name = 'DarkVapeAtmosphere'
				for prop, val in pairs(preset.Atmosphere) do
					pcall(function() atmo[prop] = val end)
				end
				if CustomFogToggle and CustomFogToggle.Enabled then
					pcall(function() atmo.Density = CustomFogDensity.Value / 100 end)
				end
				atmo.Parent = lightingService
				table.insert(newobjects, atmo)
			end
			if preset.ColorCorrection then
				local cc = Instance.new('ColorCorrectionEffect')
				cc.Name = 'DarkVapeColorCorrection'
				for prop, val in pairs(preset.ColorCorrection) do
					pcall(function() cc[prop] = val end)
				end
				cc.Parent = lightingService
				table.insert(newobjects, cc)
			end
			if preset.Bloom then
				local bloom = Instance.new('BloomEffect')
				bloom.Name = 'DarkVapeBloom'
				for prop, val in pairs(preset.Bloom) do
					pcall(function() bloom[prop] = val end)
				end
				bloom.Parent = lightingService
				table.insert(newobjects, bloom)
			end
			if preset.Clouds and workspace.Terrain then
				pcall(function()
					for _, child in ipairs(workspace.Terrain:GetChildren()) do
						if child:IsA('Clouds') and child.Name ~= 'DarkVapeClouds' then
							table.insert(oldobjects, child)
							child.Parent = nil
						end
					end
					local clouds = Instance.new('Clouds')
					clouds.Name = 'DarkVapeClouds'
					clouds.Cover = preset.Clouds.Cover or 0.85
					clouds.Density = preset.Clouds.Density or 0.85
					clouds.Color = preset.Clouds.Color or Color3.fromRGB(190, 204, 222)
					clouds.Enabled = true
					clouds.Parent = workspace.Terrain
					table.insert(newobjects, clouds)
				end)
			end
		end
	end

	configureWeatherEmitters()
	configureOceanVoid()
	nextLightning = os.clock() + math.random(3, 6)
end

Atmosphere = vape.Categories.Render:CreateModule({
	Name = 'Atmosphere',
	Function = function(callback)
		if callback then
			applyTheme()
			Atmosphere:Clean(lightingService.ChildAdded:Connect(function(v)
				task.defer(stashExistingLightingChild, v)
			end))
			Atmosphere:Clean(runService.RenderStepped:Connect(function(dt)
				local cam = workspace.CurrentCamera
				local t = os.clock()
				if weatherPart and cam then
					local wind = WindSway and WindSway.Value or 8
					local swayX = math.sin(t * 0.9) * (wind * 0.35)
					local swayZ = math.cos(t * 0.7) * (wind * 0.35)
					weatherPart.CFrame = CFrame.new(cam.CFrame.Position + Vector3.new(swayX, 42, swayZ))
				end
				if oceanDeep and cam then
					local cx, cz = cam.CFrame.Position.X, cam.CFrame.Position.Z
					oceanDeep.Position = Vector3.new(cx, (baseOceanY or 0) - 14, cz)
					if not lastTerrainWaterCenter or (Vector3.new(cx, lastTerrainWaterCenter.Y, cz) - lastTerrainWaterCenter).Magnitude > 220 then
						fillOceanTerrainAt(cx, cz)
					end
					if lplr.Character then
						local hum = lplr.Character:FindFirstChildOfClass('Humanoid')
						if hum then
							pcall(function() hum:SetStateEnabled(Enum.HumanoidStateType.Swimming, false) end)
						end
					end
				end

				local mode = Theme and Theme.Value or 'Blossom Sakura Sky'
				local preset = themePresets[mode]
				if preset and preset.DynamicRainbow then
					local speed = (ColorSpeed and ColorSpeed.Value or 15) / 100
					local h1 = (os.clock() * speed) % 1
					local h2 = (h1 + 0.32) % 1
					local c1 = Color3.fromHSV(h1, 0.68, 1)
					local c2 = Color3.fromHSV(h2, 0.72, 1)
					pcall(function()
						lightingService.ColorShift_Top = c1
						lightingService.ColorShift_Bottom = c2
						lightingService.FogColor = c1:Lerp(c2, 0.5)
						local atmo = lightingService:FindFirstChild('DarkVapeAtmosphere')
						if atmo then
							atmo.Color = c1
							atmo.Decay = c2
						end
					end)
				end

				local wMode = getResolvedWeather()
				if wMode == 'Thunderstorm' and LightningToggle and LightningToggle.Enabled then
					local now = os.clock()
					if now >= nextLightning then
						nextLightning = now + math.random(35, 75) / 10
						flashAlpha = 1
						if cam then spawnLightningBolt(cam.CFrame.Position) end
					end
					if flashAlpha > 0.01 then
						flashAlpha = math.max(0, flashAlpha - dt * 4.5)
						pcall(function()
							local baseBright = (preset and preset.Lighting and preset.Lighting.Brightness) or 0.9
							lightingService.Brightness = baseBright + flashAlpha * 3.8
							local cc = lightingService:FindFirstChild('DarkVapeColorCorrection')
							if cc then
								local baseCC = (preset and preset.ColorCorrection and preset.ColorCorrection.Brightness) or -0.07
								cc.Brightness = baseCC + flashAlpha * 0.32
							end
						end)
					end
				end
			end))
		else
			cleanupWeather()
			cleanupOcean()
			clearCustomObjects()
			restoreLightingState()
		end
	end,
	Tooltip = 'Transforms the sky & weather: Blossom Sakura Sky, Rain, Snow, Thunderstorm, Colorful Sky, Black Sky, or Custom.'
})

Theme = Atmosphere:CreateDropdown({
	Name = 'Theme',
	List = {'Blossom Sakura Sky', 'Rain', 'Snow', 'Thunderstorm', 'Colorful Sky', 'Black Sky', 'Custom'},
	Function = function(val)
		local isCustom = (val == 'Custom')
		for _, v in pairs(Toggles) do
			v.Toggle.Object.Visible = isCustom
			for _, sub in pairs(v.Objects) do
				sub.Object.Visible = isCustom and v.Toggle.Enabled
			end
		end
		if ColorSpeed then ColorSpeed.Object.Visible = (val == 'Colorful Sky') end
		if Atmosphere.Enabled then applyTheme() end
	end
})

Weather = Atmosphere:CreateDropdown({
	Name = 'Weather Effect',
	List = {'Match Theme', 'Sakura Petals', 'Rain', 'Snow', 'Thunderstorm', 'Starfall', 'None'},
	Function = function()
