	DefaultValue = 0.82,
	Darker = true,
	Function = function(h, s, v)
		local c = Color3.fromHSV(h, s, v)
		pcall(function()
			if workspace.Terrain then
				workspace.Terrain.WaterColor = c
			end
		end)
		if oceanDeep then
			oceanDeep.Color = c:Lerp(Color3.fromRGB(4, 38, 96), 0.65)
		end
	end
})

ColorSpeed = Atmosphere:CreateSlider({
	Name = 'Rainbow Speed',
	Min = 2,
	Max = 60,
	Default = 15,
	Visible = false
})

CustomTimeToggle = Atmosphere:CreateToggle({
	Name = 'Override Clock Time',
	Default = false,
	Function = function(callback)
		if CustomClockTime then CustomClockTime.Object.Visible = callback end
		if Atmosphere.Enabled then applyTheme() end
	end
})

CustomClockTime = Atmosphere:CreateSlider({
	Name = 'Clock Time',
	Min = 0,
	Max = 24,
	Decimal = 10,
	Default = 16.8,
	Darker = true,
	Visible = false,
	Function = function(val)
		if Atmosphere.Enabled and CustomTimeToggle.Enabled then
			pcall(function() lightingService.ClockTime = val end)
		end
	end
})

CustomFogToggle = Atmosphere:CreateToggle({
	Name = 'Override Fog Density',
	Default = false,
	Function = function(callback)
		if CustomFogDensity then CustomFogDensity.Object.Visible = callback end
		if Atmosphere.Enabled then applyTheme() end
	end
})

CustomFogDensity = Atmosphere:CreateSlider({
	Name = 'Fog Density',
	Min = 0,
	Max = 100,
	Default = 35,
	Suffix = '%',
	Darker = true,
	Visible = false,
	Function = function(val)
		if Atmosphere.Enabled and CustomFogToggle.Enabled then
			local atmo = lightingService:FindFirstChild('DarkVapeAtmosphere')
			if atmo then pcall(function() atmo.Density = val / 100 end) end
		end
	end
})

for i, v in pairs(apidump) do
	Toggles[i] = {Objects = {}}
	Toggles[i].Toggle = Atmosphere:CreateToggle({
		Name = i,
		Visible = false,
		Function = function(callback)
			if Atmosphere.Enabled and Theme.Value == 'Custom' then
				applyTheme()
			end
			for _, toggle in pairs(Toggles[i].Objects) do
				toggle.Object.Visible = (Theme.Value == 'Custom') and callback
			end
		end
	})

	for i2, v2 in pairs(v) do
		if v2 == 'Text' or v2 == 'Number' then
			Toggles[i].Objects[i2] = Atmosphere:CreateTextBox({
				Name = i2,
				Function = function(enter)
					if Atmosphere.Enabled and enter and Theme.Value == 'Custom' then
						applyTheme()
					end
				end,
				Darker = true,
				Default = v2 == 'Number' and '0' or nil,
				Visible = false
			})
		elseif v2 == 'Color' then
			Toggles[i].Objects[i2] = Atmosphere:CreateColorSlider({
				Name = i2,
				Function = function()
					if Atmosphere.Enabled and Theme.Value == 'Custom' then
						applyTheme()
					end
				end,
				Darker = true,
				Visible = false
			})
		end
	end
end

function Atmosphere:GetAtmosphereState()
	return {
		Enabled = Atmosphere.Enabled,
		Theme = Theme.Value,
		Weather = getResolvedWeather(),
		HasSky = lightingService:FindFirstChild('DarkVapeSky') ~= nil,
		HasAtmosphere = lightingService:FindFirstChild('DarkVapeAtmosphere') ~= nil,
		HasWeatherCanopy = weatherPart ~= nil and weatherPart.Parent ~= nil,
		HasOceanVoid = oceanSurface ~= nil and oceanSurface.Parent ~= nil,
		ClockTime = lightingService.ClockTime
	}
end

end)

