local function restoreWeaponParts()
	for part, origTrans in pairs(hiddenWeaponParts) do
		pcall(function()
			if part and part.Parent then
				part.Transparency = origTrans
				if part:IsA('BasePart') then
					part.LocalTransparencyModifier = 0
