local function hideCharacterVisual(inst)
	if not inst then return end
	if morphFolder and inst:IsDescendantOf(morphFolder) then return end
	if thirdPersonBat and inst:IsDescendantOf(thirdPersonBat) then return end
	if inst:IsA('BasePart') and inst.Name ~= 'HumanoidRootPart' then
		if hiddenParts[inst] == nil then
			hiddenParts[inst] = inst.Transparency
		end
		inst.Transparency = 1
		inst.LocalTransparencyModifier = 1
	elseif inst:IsA('Decal') or inst:IsA('Texture') then
		if hiddenParts[inst] == nil then
			hiddenParts[inst] = inst.Transparency
		end
		inst.Transparency = 1
	end
end

local function hideWeaponVisual(inst)
	if not inst then return end
	if inst:IsA('BasePart') then
		if hiddenWeaponParts[inst] == nil then
			hiddenWeaponParts[inst] = inst.Transparency
		end
		inst.Transparency = 1
		inst.LocalTransparencyModifier = 1
	elseif inst:IsA('Decal') or inst:IsA('Texture') or inst:IsA('SurfaceGui') or inst:IsA('ParticleEmitter') or inst:IsA('Trail') or inst:IsA('Beam') then
		if inst:IsA('Decal') or inst:IsA('Texture') then
			if hiddenWeaponParts[inst] == nil then
				hiddenWeaponParts[inst] = inst.Transparency
			end
			inst.Transparency = 1
		elseif inst:IsA('ParticleEmitter') or inst:IsA('Trail') or inst:IsA('Beam') then
			inst.Enabled = false
		end
	end
end

local function createSahurBatModel(attachPart, scaleMult, isViewmodel, alignAlongY)
	local batModel = Instance.new('Model')
	batModel.Name = isViewmodel and 'TungSahurViewmodelBat' or 'TungSahurBat'

	local gripAtt = attachPart:FindFirstChild('RightGripAttachment')
	local baseOffset = CFrame.identity
	if not alignAlongY and gripAtt and gripAtt:IsA('Attachment') then
		baseOffset = CFrame.new(gripAtt.Position)
	end

	local function makeSegment(name, shape, size, color, mat, offsetCF)
		local p = Instance.new('Part')
		p.Name = name
		p.Shape = shape
		p.Size = size * scaleMult
		p.Color = color
		p.Material = mat
		p.CanCollide = false
		p.CanQuery = false
		p.CanTouch = false
		p.Massless = true
		p.Anchored = false
		p.CastShadow = not isViewmodel
		p.CFrame = attachPart.CFrame * baseOffset * offsetCF
		p.Parent = batModel

		local w = Instance.new('Weld')
		w.Name = 'BatWeld_' .. name
		w.Part0 = attachPart
		w.Part1 = p
		w.C0 = baseOffset * offsetCF
		w.C1 = CFrame.identity
		w.Parent = p
		return p
	end

	local woodMain = Color3.fromRGB(172, 114, 62)
	local woodDark = Color3.fromRGB(138, 88, 44)
	local gripTape = Color3.fromRGB(82, 52, 28)

	if alignAlongY then
		-- Weapon Handle has blade along +Y axis (Cylinder X-axis rotated +90 deg around Z -> +Y)
		local rotY = CFrame.Angles(0, 0, math.rad(90))
		makeSegment('Pommel', Enum.PartType.Ball, Vector3.new(0.44, 0.44, 0.44), woodDark, Enum.Material.Wood, CFrame.new(0, -1.55 * scaleMult, 0))
		makeSegment('Grip', Enum.PartType.Cylinder, Vector3.new(1.20, 0.28, 0.28), gripTape, Enum.Material.WoodPlanks, CFrame.new(0, -0.92 * scaleMult, 0) * rotY)
		makeSegment('MidShaft', Enum.PartType.Cylinder, Vector3.new(1.40, 0.45, 0.45), woodDark, Enum.Material.Wood, CFrame.new(0, 0.25 * scaleMult, 0) * rotY)
		makeSegment('Barrel', Enum.PartType.Cylinder, Vector3.new(2.20, 0.70, 0.70), woodMain, Enum.Material.Wood, CFrame.new(0, 1.75 * scaleMult, 0) * rotY)
		makeSegment('BarrelTip', Enum.PartType.Ball, Vector3.new(0.70, 0.70, 0.70), woodMain, Enum.Material.Wood, CFrame.new(0, 2.85 * scaleMult, 0))
	else
		-- Hand part has forward blade direction along -Z axis (Cylinder X-axis rotated +90 deg around Y -> -Z)
		local rotZ = CFrame.Angles(0, math.rad(90), 0)
		makeSegment('Pommel', Enum.PartType.Ball, Vector3.new(0.44, 0.44, 0.44), woodDark, Enum.Material.Wood, CFrame.new(0, -0.15 * scaleMult, 0.58 * scaleMult))
		makeSegment('Grip', Enum.PartType.Cylinder, Vector3.new(1.20, 0.28, 0.28), gripTape, Enum.Material.WoodPlanks, CFrame.new(0, -0.15 * scaleMult, 0) * rotZ)
		makeSegment('MidShaft', Enum.PartType.Cylinder, Vector3.new(1.40, 0.45, 0.45), woodDark, Enum.Material.Wood, CFrame.new(0, -0.15 * scaleMult, -1.15 * scaleMult) * rotZ)
		makeSegment('Barrel', Enum.PartType.Cylinder, Vector3.new(2.20, 0.70, 0.70), woodMain, Enum.Material.Wood, CFrame.new(0, -0.15 * scaleMult, -2.65 * scaleMult) * rotZ)
		makeSegment('BarrelTip', Enum.PartType.Ball, Vector3.new(0.70, 0.70, 0.70), woodMain, Enum.Material.Wood, CFrame.new(0, -0.15 * scaleMult, -3.75 * scaleMult))
	end

	return batModel
end

local function updateSahurBats(char, isFirstPerson)
	if not SahurBat or not SahurBat.Enabled then
		restoreWeaponParts()
		return
	end

	local scaleMult = (ScaleSlider and ScaleSlider.Value or 100) / 100

	-- 1. Hide ALL 3rd-person weapon meshes on Character (HandInvItem & any weapon Accessories)
	if char then
		local handInv = char:FindFirstChild('HandInvItem')
		local eqTool = handInv and handInv.Value
		if eqTool and eqTool:IsA('Instance') then
			for _, p in ipairs(eqTool:GetDescendants()) do
				hideWeaponVisual(p)
			end
		end
		for _, child in ipairs(char:GetChildren()) do
			if child ~= morphFolder and child ~= thirdPersonBat and (child:IsA('Accessory') or child:IsA('Tool')) then
				for _, p in ipairs(child:GetDescendants()) do
					hideWeaponVisual(p)
				end
			end
		end
	end

	-- 2. Attach 3rd-person bat directly to Tung_RightHand (so it sits inside Tung Tung Sahur's hand!)
	local tpHand = morphedLimbMap['RightHand'] or (char and (char:FindFirstChild('RightHand') or char:FindFirstChild('Right Arm')))
	if tpHand and tpHand:IsA('BasePart') then
		if lastThirdPersonTarget ~= tpHand or not thirdPersonBat or not thirdPersonBat.Parent then
			if thirdPersonBat then pcall(function() thirdPersonBat:Destroy() end) end
			lastThirdPersonTarget = tpHand
			thirdPersonBat = createSahurBatModel(tpHand, scaleMult, false, false)
			thirdPersonBat.Parent = morphFolder or char
		end
		for _, part in ipairs(thirdPersonBat:GetDescendants()) do
			if part:IsA('BasePart') then
				part.LocalTransparencyModifier = isFirstPerson and 1 or 0
			end
		end
	end

	-- 3. Hide 1st-person sword/tool mesh in Viewmodel & attach 1st-person wooden bat
	local cam = workspace.CurrentCamera
	local vm = cam and cam:FindFirstChild('Viewmodel')
	if vm then
		local vmWeaponHandle = nil
		for _, child in ipairs(vm:GetChildren()) do
			if child ~= viewmodelBat and (child:IsA('Accessory') or child:IsA('Model') or child:IsA('Tool')) then
				local h = child:FindFirstChild('Handle')
				if h and h:IsA('BasePart') then
					vmWeaponHandle = h
				end
				for _, desc in ipairs(child:GetDescendants()) do
					hideWeaponVisual(desc)
				end
			end
		end
		for _, desc in ipairs(vm:GetDescendants()) do
			if desc:IsA('BasePart') and not desc:IsDescendantOf(viewmodelBat or vm) then
				-- already handled
			elseif desc:IsA('BasePart') and (not viewmodelBat or not desc:IsDescendantOf(viewmodelBat)) then
				if not vmLimbSet[desc.Name] then
					hideWeaponVisual(desc)
				end
			end
		end

		local vmAttachTarget = vmWeaponHandle or vm:FindFirstChild('RightHand')
		local alignY = (vmWeaponHandle ~= nil)
		if vmAttachTarget and vmAttachTarget:IsA('BasePart') then
			if lastViewmodelTarget ~= vmAttachTarget or not viewmodelBat or not viewmodelBat.Parent then
				if viewmodelBat then pcall(function() viewmodelBat:Destroy() end) end
				lastViewmodelTarget = vmAttachTarget
				viewmodelBat = createSahurBatModel(vmAttachTarget, 0.92, true, alignY)
				viewmodelBat.Parent = vm
			end
		end
	end
end

local function buildSelfESP(char)
	local cam = workspace.CurrentCamera or workspace
	local root = char and char:FindFirstChild('HumanoidRootPart')
	if not char or not root then return end

	local col = Color3.fromHSV(ESPColor.Hue, ESPColor.Sat, ESPColor.Value)

	pcall(function()
		selfHighlightObj = Instance.new('Highlight')
		selfHighlightObj.Name = 'TungTungSelfHighlight'
		selfHighlightObj.Adornee = morphFolder or char
		selfHighlightObj.DepthMode = (ThroughWalls and ThroughWalls.Enabled) and Enum.HighlightDepthMode.AlwaysOnTop or Enum.HighlightDepthMode.Occluded
		selfHighlightObj.FillColor = col
		selfHighlightObj.OutlineColor = Color3.fromRGB(255, 235, 195)
		selfHighlightObj.FillTransparency = 0.68
		selfHighlightObj.OutlineTransparency = 0
		selfHighlightObj.Enabled = SelfHighlight and SelfHighlight.Enabled or false
		selfHighlightObj.Parent = cam
	end)

	pcall(function()
		selfBoxObj = Instance.new('BoxHandleAdornment')
		selfBoxObj.Name = 'TungTungSelfBox'
		selfBoxObj.Adornee = root
		selfBoxObj.AlwaysOnTop = (ThroughWalls and ThroughWalls.Enabled) or false
		selfBoxObj.Size = Vector3.new(3.6, 5.6, 3.6)
		selfBoxObj.CFrame = CFrame.new(0, -0.2, 0)
		selfBoxObj.Color3 = col
		selfBoxObj.Transparency = 0.55
		selfBoxObj.ZIndex = 2
		selfBoxObj.Visible = SelfBox and SelfBox.Enabled or false
		selfBoxObj.Parent = cam
	end)

	pcall(function()
		billboardObj = Instance.new('BillboardGui')
		billboardObj.Name = 'TungTungBillboard'
		billboardObj.Adornee = morphedLimbMap['Head'] or char:FindFirstChild('Head') or root
		billboardObj.Size = UDim2.fromOffset(200, 42)
		billboardObj.StudsOffset = Vector3.new(0, 2.8, 0)
		billboardObj.AlwaysOnTop = true
		billboardObj.Enabled = OverheadTag and OverheadTag.Enabled or false
		billboardObj.Parent = cam

		local title = Instance.new('TextLabel')
		title.Name = 'Title'
		title.Size = UDim2.fromScale(1, 0.6)
		title.BackgroundTransparency = 1
		title.Font = Enum.Font.GothamBlack
		title.Text = 'TUNG TUNG SAHUR'
		title.TextColor3 = col
		title.TextStrokeTransparency = 0.15
		title.TextStrokeColor3 = Color3.new(0, 0, 0)
		title.TextSize = 15
		title.Parent = billboardObj

		local sub = Instance.new('TextLabel')
		sub.Name = 'Sub'
		sub.Position = UDim2.fromScale(0, 0.55)
		sub.Size = UDim2.fromScale(1, 0.45)
		sub.BackgroundTransparency = 1
		sub.Font = Enum.Font.GothamBold
		sub.Text = '100 HP • SELF ESP'
		sub.TextColor3 = Color3.fromRGB(240, 232, 255)
		sub.TextStrokeTransparency = 0.25
		sub.TextSize = 12
		sub.Parent = billboardObj
	end)
end

local function applyTungTungMorph(char)
	restoreOriginalCharacter()
	if not TungTungSahur or not TungTungSahur.Enabled or not char then return end

	local root = char:WaitForChild('HumanoidRootPart', 5)
	local hum = char:WaitForChild('Humanoid', 5)
	if not root or not hum then return end

	local targetUid = TUNG_USER_ID
	if PresetMode and PresetMode.Value == 'Custom UserId' then
		targetUid = tonumber(CustomUserId and CustomUserId.Value) or TUNG_USER_ID
	end

	local okModel, rigModel = pcall(function()
		return playersService:CreateHumanoidModelFromUserId(targetUid)
	end)
	if not okModel or not rigModel then
		local okDesc, desc = pcall(function()
			return playersService:GetHumanoidDescriptionFromUserId(targetUid)
		end)
		if okDesc and desc then
			okModel, rigModel = pcall(function()
				return playersService:CreateHumanoidModelFromDescription(desc, Enum.HumanoidRigType.R15)
			end)
			pcall(function() desc:Destroy() end)
		end
	end

	if not TungTungSahur.Enabled then
		if rigModel then pcall(function() rigModel:Destroy() end) end
		return
	end

	morphFolder = Instance.new('Model')
	morphFolder.Name = 'TungTungSahurMorph'
	morphFolder.Parent = char

	for _, desc in ipairs(char:GetDescendants()) do
		if not desc:IsDescendantOf(morphFolder) then
			if HideArmor and HideArmor.Enabled then
				hideCharacterVisual(desc)
			elseif table.find(r15LimbNames, desc.Name) or (desc.Parent and desc.Parent.Name == 'Head') then
				hideCharacterVisual(desc)
			end
		end
	end

	local scaleMult = (ScaleSlider and ScaleSlider.Value or 100) / 100

	if okModel and rigModel then
		-- 1. Clone all 15 R15 MeshParts & scale their RigAttachments so sockets match 1:1
		for _, limbName in ipairs(r15LimbNames) do
			local srcLimb = rigModel:FindFirstChild(limbName)
			local dstLimb = char:FindFirstChild(limbName)
			if srcLimb and dstLimb and srcLimb:IsA('BasePart') and dstLimb:IsA('BasePart') then
				local cloneLimb = srcLimb:Clone()
				for _, child in ipairs(cloneLimb:GetChildren()) do
					if child:IsA('Motor6D') or child:IsA('Weld') or child:IsA('WeldConstraint')
						or child:IsA('AnimationConstraint') or child:IsA('BallSocketConstraint')
						or child:IsA('NoCollisionConstraint') then
						child:Destroy()
					elseif child:IsA('Attachment') and math.abs(scaleMult - 1) > 0.01 then
						child.Position = child.Position * scaleMult
					end
				end
				cloneLimb.Name = 'Tung_' .. limbName
				cloneLimb.CanCollide = false
				cloneLimb.CanQuery = false
				cloneLimb.CanTouch = false
				cloneLimb.Massless = true
				cloneLimb.Anchored = false
				cloneLimb.CastShadow = true
				if math.abs(scaleMult - 1) > 0.01 then
					cloneLimb.Size = cloneLimb.Size * scaleMult
				end
				cloneLimb.CFrame = dstLimb.CFrame
				cloneLimb.Parent = morphFolder

				morphedLimbMap[limbName] = cloneLimb
				table.insert(morphedParts, cloneLimb)
			end
		end

		-- 2. Connect each Tung limb to its parent Tung limb at exact RigAttachment sockets
		for _, entry in ipairs(r15JointTree) do
			local childTung = morphedLimbMap[entry.child]
			local parentTung = (entry.parent == 'HumanoidRootPart') and root or morphedLimbMap[entry.parent]
			local charChild = char:FindFirstChild(entry.child)
			local charParent = char:FindFirstChild(entry.parent)

			if childTung and parentTung then
				local pAtt = (entry.parent ~= 'HumanoidRootPart') and parentTung:FindFirstChild(entry.att) or nil
				local cAtt = childTung:FindFirstChild(entry.att)
				local parentAttCF = CFrame.new((pAtt and pAtt:IsA('Attachment')) and pAtt.Position or Vector3.zero)
				local childAttCF = CFrame.new((cAtt and cAtt:IsA('Attachment')) and cAtt.Position or Vector3.zero)

				local relRot = (charParent and charChild and charParent:IsA('BasePart') and charChild:IsA('BasePart'))
					and (charParent.CFrame.Rotation:Inverse() * charChild.CFrame.Rotation)
					or CFrame.identity

				local weld = Instance.new('Weld')
				weld.Name = 'TungJoint_' .. entry.child
				weld.Part0 = parentTung
				weld.Part1 = childTung
				weld.C0 = parentAttCF * relRot
				weld.C1 = childAttCF
				weld.Parent = childTung

				table.insert(morphedJoints, {
					weld = weld,
					parentAttCF = parentAttCF,
					charParent = charParent,
					charChild = charChild
				})
			end
		end

		-- 3. Attach any bundle accessories to Tung_Head / Tung_UpperTorso
		for _, child in ipairs(rigModel:GetChildren()) do
			if child:IsA('Accessory') then
				local handle = child:FindFirstChild('Handle')
				if handle and handle:IsA('BasePart') then
					local cloneHandle = handle:Clone()
					for _, c in ipairs(cloneHandle:GetChildren()) do
						if c:IsA('Weld') or c:IsA('Motor6D') or c:IsA('WeldConstraint') then
							c:Destroy()
						end
					end
					cloneHandle.Name = 'Tung_Accessory_' .. child.Name
					cloneHandle.CanCollide = false
					cloneHandle.CanQuery = false
					cloneHandle.CanTouch = false
					cloneHandle.Massless = true
					cloneHandle.Anchored = false
					local attachTo = morphedLimbMap['Head'] or morphedLimbMap['UpperTorso'] or root
					cloneHandle.CFrame = attachTo.CFrame
					cloneHandle.Parent = morphFolder

					local weld = Instance.new('WeldConstraint')
					weld.Part0 = cloneHandle
					weld.Part1 = attachTo
					weld.Parent = cloneHandle
					table.insert(morphedParts, cloneHandle)
				end
			end
		end

		pcall(function() rigModel:Destroy() end)
	end

	buildSelfESP(char)
	updateSahurBats(char, false)
end

TungTungSahur = vape.Categories.Render:CreateModule({
	Name = 'TungTungSahur',
	Function = function(callback)
		if callback then
			if lplr.Character then
				task.spawn(applyTungTungMorph, lplr.Character)
			end
			TungTungSahur:Clean(lplr.CharacterAdded:Connect(function(newChar)
				task.wait(0.25)
				if TungTungSahur.Enabled then
					applyTungTungMorph(newChar)
				end
			end))
			TungTungSahur:Clean(runService.RenderStepped:Connect(function()
				local char = lplr.Character
				if not char then return end

				-- Update connected R15 socket joint rotations from animated character limbs
				for _, j in ipairs(morphedJoints) do
					if j.weld and j.weld.Parent and j.charParent and j.charChild and j.charParent.Parent and j.charChild.Parent then
						j.weld.C0 = j.parentAttCF * (j.charParent.CFrame.Rotation:Inverse() * j.charChild.CFrame.Rotation)
					end
				end

				-- Hide underlying character limbs & armor continuously
				for _, limbName in ipairs(r15LimbNames) do
					local limb = char:FindFirstChild(limbName)
					if limb and limb:IsA('BasePart') and limb.Transparency < 1 then
						hideCharacterVisual(limb)
					end
				end
				if HideArmor and HideArmor.Enabled then
					for _, child in ipairs(char:GetChildren()) do
						if child ~= morphFolder and child ~= thirdPersonBat and (child:IsA('Accessory') or child:IsA('Model')) then
							for _, part in ipairs(child:GetDescendants()) do
								if part:IsA('BasePart') and part.Transparency < 1 then
									hideCharacterVisual(part)
								end
							end
						end
					end
				end

				local cam = workspace.CurrentCamera
				local isFirstPerson = cam and ((cam.CFrame.Position - cam.Focus.Position).Magnitude <= 0.75) or false
				for _, part in ipairs(morphedParts) do
					if part and part.Parent then
						part.LocalTransparencyModifier = isFirstPerson and 1 or 0
					end
				end

				updateSahurBats(char, isFirstPerson)

				local col = (RainbowESP and RainbowESP.Enabled)
					and Color3.fromHSV((os.clock() * 0.28) % 1, 0.75, 1)
					or Color3.fromHSV(ESPColor.Hue, ESPColor.Sat, ESPColor.Value)

				if selfHighlightObj then
					selfHighlightObj.Enabled = (SelfHighlight and SelfHighlight.Enabled and not isFirstPerson) or false
					selfHighlightObj.DepthMode = (ThroughWalls and ThroughWalls.Enabled) and Enum.HighlightDepthMode.AlwaysOnTop or Enum.HighlightDepthMode.Occluded
					selfHighlightObj.FillColor = col
				end
				if selfBoxObj then
					selfBoxObj.Visible = (SelfBox and SelfBox.Enabled and not isFirstPerson) or false
					selfBoxObj.AlwaysOnTop = (ThroughWalls and ThroughWalls.Enabled) or false
					selfBoxObj.Color3 = col
				end
				if billboardObj then
					billboardObj.Enabled = (OverheadTag and OverheadTag.Enabled and not isFirstPerson) or false
					local title = billboardObj:FindFirstChild('Title')
					local sub = billboardObj:FindFirstChild('Sub')
					if title then title.TextColor3 = col end
					if sub then
						local hum = char:FindFirstChildOfClass('Humanoid')
						local hp = math.round(char:GetAttribute('Health') or (hum and hum.Health) or 100)
						sub.Text = tostring(hp) .. ' HP • TUNG TUNG SAHUR'
					end
				end
			end))
		else
			restoreOriginalCharacter()
		end
	end,
	Tooltip = 'Morphs your character into Tung Tung Sahur (UserId 10370212978), turns your sword into his wooden bat, and adds Self ESP.'
})

PresetMode = TungTungSahur:CreateDropdown({
	Name = 'Character',
	List = {'Tung Tung Sahur', 'Custom UserId'},
	Function = function(val)
		if CustomUserId then CustomUserId.Object.Visible = (val == 'Custom UserId') end
		if TungTungSahur.Enabled and lplr.Character then
			task.spawn(applyTungTungMorph, lplr.Character)
		end
	end
})

CustomUserId = TungTungSahur:CreateTextBox({
	Name = 'UserId',
	Default = '10370212978',
	Placeholder = '10370212978',
	Visible = false,
	Darker = true,
	Function = function(enter)
		if enter and TungTungSahur.Enabled and lplr.Character then
			task.spawn(applyTungTungMorph, lplr.Character)
		end
	end
})

SahurBat = TungTungSahur:CreateToggle({
	Name = 'Sahur Wooden Bat Sword',
	Default = true,
	Function = function(enabled)
		if not enabled then
			restoreWeaponParts()
		end
	end
})

SelfHighlight = TungTungSahur:CreateToggle({
	Name = 'Self Highlight ESP',
	Default = true
})

ThroughWalls = TungTungSahur:CreateToggle({
	Name = 'ESP Through Walls',
	Default = true
})

SelfBox = TungTungSahur:CreateToggle({
