	Default = true,
	Function = function()
		if TungTungSahur.Enabled and lplr.Character then
			task.spawn(applyTungTungMorph, lplr.Character)
		end
	end
})

RainbowESP = TungTungSahur:CreateToggle({
	Name = 'Rainbow Self ESP',
	Default = false
