-- Lua / AntiFall.lua / Luau / x64 / Windows / Roblox BedWars (6872274481)

local AntiFallDirection
run(function()
	local AntiFall
	local Mode
	local DropDistance
	local BouncePower
	local PullToLedge
	local Material
	local Color
	local ShowPlatform
	local rayCheck = RaycastParams.new()
	rayCheck.FilterType = Enum.RaycastFilterType.Exclude
	rayCheck.RespectCanCollide = true

	local lastSafePos = nil

	local function sendSafeGroundHit()
		pcall(function()
			local gh = (remotes and remotes.GroundHit and bedwars.Client:Get(remotes.GroundHit).instance)
				or replicatedStorage.rbxts_include.node_modules['@rbxts'].net.out._NetManaged:FindFirstChild('GroundHit')
			if gh then
				gh:FireServer(nil, Vector3.new(0, -10, 0), workspace:GetServerTimeNow())
			end
		end)
	end

	local function getExcludeList()
		local list = {lplr.Character, gameCamera, AntiFallPart}
		local ocean = workspace:FindFirstChild('DarkVapeOceanVoid')
		if ocean then table.insert(list, ocean) end
		local weather = workspace:FindFirstChild('DarkVapeWeatherCanopy')
		if weather then table.insert(list, weather) end
		return list
	end

	AntiFall = vape.Categories.Blatant:CreateModule({
		Name = 'AntiFall',
		Function = function(callback)
			if callback then
				if entitylib.isAlive and entitylib.character and entitylib.character.RootPart then
					lastSafePos = entitylib.character.RootPart.Position
				else
					lastSafePos = Vector3.new(0, 30, 0)
				end
				local debounce = 0

				AntiFallPart = Instance.new('Part')
				AntiFallPart.Name = 'DarkVapeAntiFallPart'
				AntiFallPart.Size = Vector3.new(10000, 2, 10000)
				AntiFallPart.Transparency = ShowPlatform.Enabled and (1 - Color.Opacity) or 1
				AntiFallPart.Material = Enum.Material[Material.Value]
				AntiFallPart.Color = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
				AntiFallPart.CanCollide = (Mode.Value == 'Collide')
				AntiFallPart.Anchored = true
				AntiFallPart.CanQuery = false
				AntiFallPart.CanTouch = true
				AntiFallPart.Position = Vector3.new(lastSafePos.X, lastSafePos.Y - DropDistance.Value, lastSafePos.Z)
				AntiFallPart.Parent = workspace

				AntiFall:Clean(function()
					if AntiFallPart then
						pcall(function() AntiFallPart:Destroy() end)
						AntiFallPart = nil
					end
					AntiFallDirection = nil
				end)

				local function triggerRecovery(root, hum, catchY)
					local now = os.clock()
					if now < debounce then return end
					debounce = now + 0.10
					sendSafeGroundHit()

					local safeTarget = (getNearGround and getNearGround(14)) or lastSafePos
					local toSafe = safeTarget and ((safeTarget - root.Position) * Vector3.new(1, 0, 1)) or Vector3.zero
					local dirToSafe = toSafe.Magnitude > 0.15 and toSafe.Unit or Vector3.zero

					local curMode = Mode.Value
					if curMode == 'Bounce' or curMode == 'Velocity' then
						local nextPos = Vector3.new(root.Position.X, math.max(root.Position.Y, catchY + 2.2), root.Position.Z)
						if PullToLedge.Enabled and toSafe.Magnitude > 0.2 then
							local stepDist = math.min(toSafe.Magnitude, 5.5)
							nextPos = nextPos + dirToSafe * stepDist
							AntiFallDirection = dirToSafe
							task.delay(0.32, function()
								AntiFallDirection = nil
							end)
						end
						root.CFrame = CFrame.new(nextPos) * root.CFrame.Rotation
						local horizVel = (PullToLedge.Enabled and dirToSafe.Magnitude > 0)
							and (dirToSafe * (getSpeed and getSpeed() or 22))
							or Vector3.new(root.AssemblyLinearVelocity.X, 0, root.AssemblyLinearVelocity.Z)
						root.AssemblyLinearVelocity = Vector3.new(horizVel.X, BouncePower.Value, horizVel.Z)
						pcall(function()
							if hum then hum:ChangeState(Enum.HumanoidStateType.Jumping) end
						end)
					elseif curMode == 'Teleport Safe' then
						if safeTarget then
							local delta = safeTarget + Vector3.new(0, 3.2, 0) - root.Position
							local maxStep = 14
							local targetPos = delta.Magnitude > maxStep
								and (root.Position + delta.Unit * maxStep + Vector3.new(0, 2.5, 0))
								or (safeTarget + Vector3.new(0, 3.2, 0))
							root.AssemblyLinearVelocity = Vector3.new(0, 18, 0)
							root.CFrame = CFrame.new(targetPos) * root.CFrame.Rotation
						else
							root.AssemblyLinearVelocity = Vector3.new(root.AssemblyLinearVelocity.X, BouncePower.Value, root.AssemblyLinearVelocity.Z)
						end
					elseif curMode == 'Normal' then
						if safeTarget then
							AntiFallDirection = dirToSafe
							local stepDist = math.min(toSafe.Magnitude, 6.0)
							local nextY = math.min(safeTarget.Y + 2.8, root.Position.Y + 10)
							root.CFrame = CFrame.new(root.Position.X + dirToSafe.X * stepDist, nextY, root.Position.Z + dirToSafe.Z * stepDist) * root.CFrame.Rotation
							root.AssemblyLinearVelocity = dirToSafe * (getSpeed and getSpeed() or 22) + Vector3.new(0, math.min(BouncePower.Value, 58), 0)
							task.delay(0.30, function()
								AntiFallDirection = nil
							end)
						else
							root.AssemblyLinearVelocity = Vector3.new(root.AssemblyLinearVelocity.X, BouncePower.Value, root.AssemblyLinearVelocity.Z)
						end
					elseif curMode == 'Collide' then
						if root.Position.Y < catchY + 2.2 then
							root.CFrame = CFrame.new(root.Position.X, catchY + 3.2, root.Position.Z) * root.CFrame.Rotation
							root.AssemblyLinearVelocity = Vector3.new(root.AssemblyLinearVelocity.X, 0, root.AssemblyLinearVelocity.Z)
						end
					end
				end

				AntiFall:Clean(AntiFallPart.Touched:Connect(function(touched)
					if entitylib.isAlive and lplr.Character and touched:IsDescendantOf(lplr.Character) then
						local root = entitylib.character.RootPart
						local hum = entitylib.character.Humanoid
						if root then
							triggerRecovery(root, hum, AntiFallPart.Position.Y + 1)
						end
					end
				end))

				AntiFall:Clean(runService.PreSimulation:Connect(function()
					if not entitylib.isAlive then return end
					if (vape.Modules.Fly and vape.Modules.Fly.Enabled) or (vape.Modules.InfiniteFly and vape.Modules.InfiniteFly.Enabled) then
						return
					end
					local root = entitylib.character.RootPart
					local hum = entitylib.character.Humanoid
					if not root or not hum then return end

					rayCheck.FilterDescendantsInstances = getExcludeList()

					-- Record last safe island/bridge position when standing on real ground
					if hum.FloorMaterial ~= Enum.Material.Air then
						local floorHit = workspace:Raycast(root.Position, Vector3.new(0, -7, 0), rayCheck)
						if floorHit and floorHit.Instance and floorHit.Instance ~= AntiFallPart and floorHit.Instance.Transparency < 0.85 then
							lastSafePos = root.Position
						end
					end

					if not lastSafePos then
						lastSafePos = root.Position
					end

					-- Check if there is solid playable ground directly below within 25 studs
					local groundBelow = workspace:Raycast(root.Position, Vector3.new(0, -25, 0), rayCheck)
					local hasSolidGroundBelow = groundBelow
						and groundBelow.Instance
						and groundBelow.Instance ~= AntiFallPart
						and groundBelow.Instance.CanCollide
						and groundBelow.Instance.Transparency < 0.85

					local refY = lastSafePos.Y
					if hasSolidGroundBelow and groundBelow.Position.Y < refY then
						refY = groundBelow.Position.Y + 3
					end

					local catchY = refY - DropDistance.Value
					local isOverVoid = not hasSolidGroundBelow

					if AntiFallPart then
						AntiFallPart.Position = Vector3.new(root.Position.X, catchY - 1, root.Position.Z)
						AntiFallPart.CanCollide = (Mode.Value == 'Collide') or (isOverVoid and root.Position.Y <= catchY + 3.5)
					end

					if isOverVoid and root.Position.Y <= catchY + 2.5 and root.AssemblyLinearVelocity.Y <= 2 then
						triggerRecovery(root, hum, catchY)
					end
				end))
			else
				AntiFallDirection = nil
			end
		end,
		Tooltip = 'Prevents falling into the void by catching you right below the island edge and bouncing/pulling you back onto safe ground.'
	})

	Mode = AntiFall:CreateDropdown({
		Name = 'Move Mode',
		List = {'Bounce', 'Normal', 'Collide', 'Teleport Safe', 'Velocity'},
		Function = function(val)
			if AntiFallPart then
				AntiFallPart.CanCollide = (val == 'Collide')
			end
		end,
		Tooltip = 'Bounce - Bounces & pulls you back onto the island edge\nNormal - Pulls you toward nearest block\nCollide - Walkable void platform right below island\nTeleport Safe - Teleports to last safe ground'
	})

	DropDistance = AntiFall:CreateSlider({
		Name = 'Trigger Drop',
		Min = 3,
		Max = 25,
		Default = 7,
		Suffix = 'studs',
		Tooltip = 'How many studs below the island edge before AntiFall catches you.'
	})

	BouncePower = AntiFall:CreateSlider({
		Name = 'Bounce Velocity',
		Min = 35,
		Max = 110,
		Default = 62
	})

	PullToLedge = AntiFall:CreateToggle({
		Name = 'Pull To Safe Ledge',
		Default = true,
		Tooltip = 'Automatically steers and steps you back onto the nearest island/bridge block when bouncing out of the void.'
	})

	ShowPlatform = AntiFall:CreateToggle({
		Name = 'Show Platform',
		Default = true,
		Function = function(enabled)
			if AntiFallPart then
				AntiFallPart.Transparency = enabled and (1 - Color.Opacity) or 1
			end
		end
	})

	local materials = {'ForceField'}
	for _, v in Enum.Material:GetEnumItems() do
		if v.Name ~= 'ForceField' then
			table.insert(materials, v.Name)
		end
	end
	Material = AntiFall:CreateDropdown({
		Name = 'Material',
		List = materials,
		Function = function(val)
			if AntiFallPart then
				AntiFallPart.Material = Enum.Material[val]
			end
		end
	})

	Color = AntiFall:CreateColorSlider({
		Name = 'Color',
		DefaultHue = 0.746,
		DefaultSat = 0.60,
		DefaultValue = 0.92,
		DefaultOpacity = 0.45,
		Function = function(h, s, v, o)
			if AntiFallPart then
				AntiFallPart.Color = Color3.fromHSV(h, s, v)
				AntiFallPart.Transparency = ShowPlatform.Enabled and (1 - o) or 1
			end
		end
	})
end)

run(function()
	local InfiniteJump
	local Mode
	local JumpPower
	local HoldSpace
	local HoldCooldown
	local PreventFall
	local lastJump = 0

	local function sendSafeGroundHit()
		if not PreventFall or not PreventFall.Enabled then return end
		pcall(function()
			local gh = (remotes and remotes.GroundHit and bedwars.Client:Get(remotes.GroundHit).instance)
				or replicatedStorage.rbxts_include.node_modules['@rbxts'].net.out._NetManaged:FindFirstChild('GroundHit')
			if gh then
				gh:FireServer(nil, Vector3.new(0, -10, 0), workspace:GetServerTimeNow())
			end
		end)
	end

	local function performAirJump()
		if not entitylib.isAlive then return end
		if inputService:GetFocusedTextBox() then return end
		if vape.gui and vape.gui.ScaledGui and vape.gui.ScaledGui.ClickGui.Visible then return end
		local root = entitylib.character.RootPart
		local hum = entitylib.character.Humanoid
		if not root or not hum then return end

		local now = os.clock()
		if now - lastJump < (HoldCooldown and HoldCooldown.Value or 0.14) then return end
		lastJump = now

		sendSafeGroundHit()
		local m = Mode and Mode.Value or 'Velocity'
		if m == 'Velocity' then
			local vel = root.AssemblyLinearVelocity
			root.AssemblyLinearVelocity = Vector3.new(vel.X, JumpPower.Value, vel.Z)
		elseif m == 'State' then
			pcall(function()
				hum:ChangeState(Enum.HumanoidStateType.Jumping)
			end)
			local vel = root.AssemblyLinearVelocity
			if vel.Y < JumpPower.Value then
				root.AssemblyLinearVelocity = Vector3.new(vel.X, JumpPower.Value, vel.Z)
			end
		elseif m == 'Jetpack' then
			local vel = root.AssemblyLinearVelocity
			root.AssemblyLinearVelocity = Vector3.new(vel.X, math.max(vel.Y + JumpPower.Value * 0.45, JumpPower.Value * 0.8), vel.Z)
		end
	end

	InfiniteJump = vape.Categories.Blatant:CreateModule({
		Name = 'InfiniteJump',
		Function = function(callback)
			if callback then
				lastJump = 0
				InfiniteJump:Clean(inputService.InputBegan:Connect(function(input, gameProcessed)
					if gameProcessed then return end
					if input.KeyCode == Enum.KeyCode.Space then
						performAirJump()
					end
				end))
				InfiniteJump:Clean(inputService.JumpRequest:Connect(function()
					if HoldSpace and HoldSpace.Enabled then
						performAirJump()
					end
				end))
				InfiniteJump:Clean(runService.Heartbeat:Connect(function()
					if HoldSpace and HoldSpace.Enabled and inputService:IsKeyDown(Enum.KeyCode.Space) then
						performAirJump()
					end
				end))
			end
		end,
		Tooltip = 'Lets you jump infinitely in mid-air with customizable jump velocity and fall-damage protection.'
	})

	Mode = InfiniteJump:CreateDropdown({
		Name = 'Mode',
		List = {'Velocity', 'State', 'Jetpack'}
	})

	JumpPower = InfiniteJump:CreateSlider({
		Name = 'Jump Velocity',
		Min = 25,
		Max = 120,
		Default = 52
	})

	HoldSpace = InfiniteJump:CreateToggle({
		Name = 'Hold Spacebar',
		Default = true,
		Function = function(enabled)
			if HoldCooldown then HoldCooldown.Object.Visible = enabled end
		end
	})

	HoldCooldown = InfiniteJump:CreateSlider({
		Name = 'Repeat Delay',
		Min = 0.05,
		Max = 0.5,
		Decimal = 100,
		Default = 0.15,
		Suffix = 's',
		Darker = true
	})

	PreventFall = InfiniteJump:CreateToggle({
		Name = 'Prevent Fall Damage',
		Default = true
	})
end)


run(function()
	local FastBreak
	local Time
	
	FastBreak = vape.Categories.Blatant:CreateModule({
		Name = 'FastBreak',
		Function = function(callback)
			if callback then
				repeat
					bedwars.BlockBreakController.blockBreaker:setCooldown(Time.Value)
					task.wait(0.1)
				until not FastBreak.Enabled
			else
				bedwars.BlockBreakController.blockBreaker:setCooldown(0.3)
