local function isAlive(char)
	if not char then return false, 0, 100 end
	local ok, alive, hp, maxHp = pcall(function()
		if char:FindFirstChildOfClass('ForceField') then return false, 0, 100 end
		local hum = char:FindFirstChildOfClass('Humanoid')
		local attrHp = char:GetAttribute('Health')
		local attrMax = char:GetAttribute('MaxHealth')
		if type(attrHp) == 'number' then
			local m = type(attrMax) == 'number' and attrMax or (hum and hum.MaxHealth) or 100
			return attrHp > 0, attrHp, m
		end
		if hum then
			return hum.Health > 0, hum.Health, hum.MaxHealth > 0 and hum.MaxHealth or 100
		end
		if collectionService:HasTag(char, 'entity') then
			return true, 100, 100
		end
		return false, 0, 100
	end)
	if ok then return alive, hp, maxHp end
	return false, 0, 100
end

