		if posMode == 'Right' then
			profileFrame.Position = UDim2.new(1, -272, 0.5, -43)
		elseif posMode == 'Left' then
			profileFrame.Position = UDim2.new(0, 20, 0.5, -43)
		else
			profileFrame.Position = UDim2.new(0.5, 45, 0.58, 0)
		end

		local plr = primary.Player
		local display = plr and plr.DisplayName or primary.Name
		local handle = plr and ('@'..plr.Name) or 'Practice / NPC'
		local distStr = string.format('%.1f studs', primary.Distance)

		nameLabel.Text = display
		subLabel.Text = handle .. '  •  ' .. distStr .. (inAttackRange and '  [HIT]' or '  [NEAR]')

		if lastCardTargetName ~= primary.Name then
			lastCardTargetName = primary.Name
			if plr and plr.UserId and plr.UserId > 0 then
				avatarImage.Image = 'rbxthumb://type=AvatarHeadShot&id='..tostring(plr.UserId)..'&w=150&h=150'
			else
				local npcOwner = primary.Character and primary.Character:GetAttribute('PlayerUserId')
				local uid = (type(npcOwner) == 'number' and npcOwner > 0) and npcOwner or lplr.UserId
				avatarImage.Image = 'rbxthumb://type=AvatarHeadShot&id='..tostring(uid)..'&w=150&h=150'
			end
		end

		local hp = math.max(0, math.round(primary.Health or 0))
		local maxHp = math.max(1, math.round(primary.MaxHealth or 100))
		local ratio = math.clamp(hp / maxHp, 0, 1)
		hpBarFill.Size = UDim2.new(ratio, 0, 1, 0)

		local col = inAttackRange and Color3.fromHSV(AttackColor.Hue, AttackColor.Sat, AttackColor.Value)
			or Color3.fromHSV(TargetColor.Hue, TargetColor.Sat, TargetColor.Value)
		hpBarFill.BackgroundColor3 = col
		if hpStroke then hpStroke.Color = col end
		hpTextLabel.Text = tostring(hp) .. ' / ' .. tostring(maxHp) .. ' HP'
		profileFrame.Visible = true
	end)
end

local function updateVisuals(targetChar, targetRoot, inAttackRange)
	local show = ShowTarget and ShowTarget.Enabled and targetChar ~= nil
	local colSlider = inAttackRange and AttackColor or TargetColor
	local col = Color3.fromHSV(colSlider.Hue, colSlider.Sat, colSlider.Value)
	local style = HighlightStyle and HighlightStyle.Value or 'Highlight'
	local myRoot = getLocalRoot()

	pcall(function()
		if auraRingAdorn then
			local showRing = ShowAuraRing and ShowAuraRing.Enabled and myRoot ~= nil
			if showRing then
				local r = Range and Range.Value or 20
				auraRingAdorn.Adornee = myRoot
				auraRingAdorn.Radius = r
				auraRingAdorn.InnerRadius = math.max(0.5, r - 0.22)
				auraRingAdorn.Color3 = col
				auraRingAdorn.Transparency = inAttackRange and 0.18 or 0.48
				auraRingAdorn.CFrame = CFrame.new(0, -2.6, 0) * CFrame.Angles(math.rad(90), 0, 0)
				auraRingAdorn.Visible = true
			else
				if auraRingAdorn.Visible then auraRingAdorn.Visible = false end
				if auraRingAdorn.Adornee ~= nil then auraRingAdorn.Adornee = nil end
			end
		end
		if highlight then
			local useHighlight = show and (style == 'Highlight' or style == 'Both')
			if useHighlight then
				if highlight.Adornee ~= targetChar then
					highlight.Adornee = targetChar
				end
				highlight.FillColor = col
				highlight.OutlineColor = col
				highlight.FillTransparency = FillAlpha and (1 - FillAlpha.Value / 100) or 0.75
				highlight.OutlineTransparency = OutlineAlpha and (1 - OutlineAlpha.Value / 100) or 0
				highlight.Enabled = true
			else
				if highlight.Enabled then highlight.Enabled = false end
				if highlight.Adornee ~= nil then highlight.Adornee = nil end
			end
		end
		if boxAdorn then
			local useBox = show and targetRoot ~= nil and (style == 'Box' or style == 'Both')
			if useBox then
				if boxAdorn.Adornee ~= targetRoot then
					boxAdorn.Adornee = targetRoot
				end
				boxAdorn.Color3 = col
				boxAdorn.Transparency = FillAlpha and (1 - FillAlpha.Value / 100) or 0.55
				boxAdorn.Visible = true
			else
				if boxAdorn.Visible then boxAdorn.Visible = false end
				if boxAdorn.Adornee ~= nil then boxAdorn.Adornee = nil end
			end
		end
	end)
end

