local function collectTargets(myRoot)
	local candidates = {}
	local maxRange = math.max(Range.Value, SwingRange.Value)
	local camera = workspace.CurrentCamera
	local facing = myRoot.CFrame.LookVector
	local flatFacing = Vector3.new(facing.X, 0, facing.Z)
	if flatFacing.Magnitude > 0.001 then flatFacing = flatFacing.Unit else flatFacing = facing end

	local function evaluateCandidate(name, char, targetRoot, hp, maxHp, isNpc, plrObj)
		local delta = targetRoot.Position - myRoot.Position
		local distance = delta.Magnitude
		if distance > maxRange or distance < 0.01 then return end

		if Angle.Value < 360 then
			local flatDelta = Vector3.new(delta.X, 0, delta.Z)
			local unitDelta = flatDelta.Magnitude > 0.001 and flatDelta.Unit or delta.Unit
			local deg = math.deg(math.acos(math.clamp(flatFacing:Dot(unitDelta), -1, 1)))
			if deg > Angle.Value / 2 then return end
		end

		if WallCheck.Enabled then
			rayParams.FilterDescendantsInstances = {lplr.Character, char, camera}
			if workspace:Raycast(myRoot.Position, delta, rayParams) then return end
		end

		local score = distance
		local sortMode = Sort.Value
		if sortMode == 'Lowest Health' then
			score = hp + distance * 0.01
		elseif sortMode == 'Highest Health' then
			score = -hp + distance * 0.01
		elseif sortMode == 'Crosshair' and camera then
			local point, visible = camera:WorldToViewportPoint(targetRoot.Position)
			if not visible then return end
			score = (Vector2.new(point.X, point.Y) - camera.ViewportSize / 2).Magnitude
		elseif sortMode == 'Angle' then
			score = math.deg(math.acos(math.clamp(flatFacing:Dot(delta.Unit), -1, 1)))
		end

		table.insert(candidates, {
			Name = name,
			Character = char,
			Root = targetRoot,
			Distance = distance,
			Health = hp,
			MaxHealth = maxHp,
			Score = score,
			IsNPC = isNpc,
			Player = plrObj
		})
	end

	local seenModels = {[lplr.Character] = true}

	if PlayersToggle.Enabled then
		for _, plr in ipairs(playersService:GetPlayers()) do
			if plr == lplr then continue end
			if plr.Character then seenModels[plr.Character] = true end
			if isSameTeam(plr) then continue end
			if isWhitelistedOrFriend(plr) then continue end
			local char = plr.Character
			if not char then continue end
			local alive, hp, maxHp = isAlive(char)
			if not alive then continue end
			if IgnoreInvisible.Enabled and isInvisible(char) then continue end
			if IgnoreNaked.Enabled and isNaked(plr) then continue end
			local hrp = char:FindFirstChild('HumanoidRootPart') or char.PrimaryPart
			if not hrp then continue end
			evaluateCandidate(plr.Name, char, hrp, hp, maxHp, false, plr)
		end
	end

	if NPCsToggle.Enabled then
		local ownTeam = lplr:GetAttribute('Team')
		local function tryNpcModel(char, rootHint)
			if not char or seenModels[char] then return end
			seenModels[char] = true
			if char.Name == 'Shopkeeper' or char.Name:lower():find('shop') or char.Name:lower():find('upgrade') then return end
			local npcTeam = char:GetAttribute('Team')
			if ownTeam ~= nil and npcTeam ~= nil and tostring(ownTeam) == tostring(npcTeam) then return end
			local ownerUserId = char:GetAttribute('PlayerUserId')
			if ownerUserId and ownerUserId == lplr.UserId then return end
			local alive, hp, maxHp = isAlive(char)
			if not alive then return end
			local rootPart = rootHint or char:FindFirstChild('HumanoidRootPart') or char.PrimaryPart or char:FindFirstChildWhichIsA('BasePart')
			if not rootPart then return end
			evaluateCandidate(char.Name, char, rootPart, hp, maxHp, true, nil)
		end

		if entitylib and entitylib.List then
			for _, ent in ipairs(entitylib.List) do
				if ent.NPC and ent.Character then
					tryNpcModel(ent.Character, ent.RootPart)
				end
			end
		end
		for _, tagged in ipairs(collectionService:GetTagged('entity')) do
			if tagged:IsA('Model') then
				tryNpcModel(tagged, nil)
			end
		end
	end

	table.sort(candidates, function(a, b)
		return a.Score < b.Score
	end)

	return candidates
end

-- Dual-Mode Extended HitAura SwordHit function:
-- 1) Inside normal range (<= 14.0 studs): fires exact unmodified Lutosys payload for 100% close-range reliability
-- 2) Extended HitAura range (14.0 - 25.0 studs): splits reach extension across selfPosition (+5.8) and targetPosition (-4.5) + raycast + micro-step
local function swordAttack(myRoot, targetEntry, tool)
	pcall(function()
		if not SwordEvent then return end
		local plrChar = targetEntry.Character or targetEntry.Root:FindFirstAncestorOfClass('Model')
		if not plrChar then return end
		local actualRoot = plrChar.PrimaryPart or targetEntry.Root
		if not actualRoot then return end

		ensureServerEquipped(tool)

		local selfpos = myRoot.Position
		local tpos = actualRoot.Position
		local delta = tpos - selfpos
		local dist = delta.Magnitude
		local dir = dist > 0.001 and (delta / dist) or myRoot.CFrame.LookVector
		local cr = ChargeRatio.Value / 100

		if bedwars and bedwars.SwordController then
			bedwars.SwordController.lastAttack = workspace:GetServerTimeNow()
		end

		if not (ExtendReach and ExtendReach.Enabled) or dist <= 14.0 then
			SwordEvent:FireServer({
				chargedAttack = {
					chargeRatio = cr
				},
				entityInstance = plrChar,
				validate = {
					selfPosition = {
						value = selfpos
					},
					targetPosition = {
						value = tpos
					}
				},
				weapon = tool
			})
			stats.Requests += 1
			return
		end

		-- Extended HitAura reach (14.0 to 25.0 studs)
		local selfStep = math.min(math.max(dist - 14.2, 0), 5.8)
		local pos = selfpos + dir * selfStep
		local rem = math.max((tpos - pos).Magnitude - 14.2, 0)
		local tposClamped = tpos - dir * math.min(rem, 4.5)

		SwordEvent:FireServer({
			weapon = tool,
			chargedAttack = {
				chargeRatio = cr
			},
			entityInstance = plrChar,
			validate = {
				raycast = {
					cameraPosition = {
						value = pos
					},
					cursorDirection = {
						value = dir
					}
				},
				selfPosition = {
					value = pos
				},
				targetPosition = {
					value = tposClamped
				}
			}
		})
		stats.Requests += 1
	end)
end

local function step()
	local myRoot = getLocalRoot()
	local char = lplr.Character
	local alive = isAlive(char)
	if not myRoot or not alive then
		clearTarget('waiting for character')
		return
	end

	local clickGuiOpen = false
	local layerOpen = false
	if Pause.Enabled then
		pcall(function()
			clickGuiOpen = vape.gui and vape.gui.ScaledGui and vape.gui.ScaledGui.ClickGui.Visible or false
		end)
		if not clickGuiOpen and bedwars and bedwars.AppController then
			pcall(function()
				layerOpen = bedwars.AppController:isLayerOpen(bedwars.UILayers.MAIN)
			end)
		end
	end
	if inputService:GetFocusedTextBox() or (Pause.Enabled and (clickGuiOpen or layerOpen)) then
		clearTarget('menu open')
		return
	end

	if Mouse.Enabled and not inputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) then
		clearTarget('hold left mouse')
		return
	end

	local targets = collectTargets(myRoot)
	stats.TargetsInRange = #targets
	local primary = targets[1]
	if not primary then
		clearTarget('no target in range')
		return
	end

	local inAttackRange = primary.Distance <= Range.Value
	local inSwingRange = primary.Distance <= math.max(Range.Value, SwingRange.Value)
	stats.Target = primary.Name
	stats.Distance = math.floor(primary.Distance * 100) / 100

	updateVisuals(primary.Character, primary.Root, inAttackRange)
	updateProfileCard(primary, inAttackRange)

	local tool, handType = getHandMelee(inSwingRange)
	if not tool or not handType then
		stats.Weapon = ''
		stats.Status = 'equip a melee weapon'
		Attacking = false
		return
	end
	stats.Weapon = handType
	stats.Status = inAttackRange and 'attacking' or 'swinging'
	Attacking = inSwingRange

	if FaceTarget.Enabled and inAttackRange then
		pcall(function()
			local lookPos = Vector3.new(primary.Root.Position.X, myRoot.Position.Y, primary.Root.Position.Z)
			if (lookPos - myRoot.Position).Magnitude > 0.05 then
				myRoot.CFrame = CFrame.lookAt(myRoot.Position, lookPos)
			end
		end)
	end

	local now = os.clock()
	if Swing.Enabled and inSwingRange and now >= nextSwing then
		nextSwing = now + math.max(1 / Rate.Value, 0.08)
		task.spawn(function()
			local ok, err = pcall(function()
				local meta = bedwars and bedwars.ItemMeta and bedwars.ItemMeta[handType]
				if meta and bedwars.SwordController then
					bedwars.SwordController:playSwordEffect(meta, false)
					stats.Swings += 1
				end
			end)
			if not ok then
				stats.AnimationError = tostring(err)
			end
		end)
	end

	if not inAttackRange or now < nextAttack then
		return
	end
	nextAttack = now + (1 / Rate.Value)

	local maxHits = math.min(#targets, MaxTargets.Value)
	for i = 1, maxHits do
		local t = targets[i]
		if t and t.Distance <= Range.Value then
			swordAttack(myRoot, t, tool)
		end
	end
end

Killaura = vape.Categories.Blatant:CreateModule({
	Name = 'Killaura',
	Function = function(enabled)
		nextAttack = 0
		nextSwing = 0
		lastCardTargetName = ''
		if not enabled then
			clearTarget('off')
			pcall(function() if highlight then highlight:Destroy() end end)
			pcall(function() if boxAdorn then boxAdorn:Destroy() end end)
			pcall(function() if auraRingAdorn then auraRingAdorn:Destroy() end end)
			pcall(function() if profileGui then profileGui:Destroy() end end)
			highlight = nil
			boxAdorn = nil
			auraRingAdorn = nil
			profileGui = nil
			profileFrame = nil
			return
		end

		if not upgradedSavedRange then
			upgradedSavedRange = true
			pcall(function()
				if Range and Range.Value < 19 then Range:SetValue(20) end
				if SwingRange and SwingRange.Value < 21 then SwingRange:SetValue(22) end
				if Rate and Rate.Value < 16 then Rate:SetValue(18) end
				if MaxTargets and MaxTargets.Value < 2 then MaxTargets:SetValue(3) end
				if Pause and Pause.Enabled then Pause:Toggle() end
				if AutoSwitch and not AutoSwitch.Enabled then AutoSwitch:Toggle() end
			end)
		end

		local parentContainer = workspace.CurrentCamera or workspace
		pcall(function()
			highlight = Instance.new('Highlight')
			highlight.Name = 'DarkVapeAuraTarget'
			highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
			highlight.FillTransparency = 0.75
			highlight.FillColor = Color3.fromRGB(139, 92, 246)
			highlight.OutlineTransparency = 0
			highlight.OutlineColor = Color3.fromRGB(176, 126, 245)
			highlight.Adornee = nil
			highlight.Enabled = false
			highlight.Parent = parentContainer
		end)

		pcall(function()
			boxAdorn = Instance.new('BoxHandleAdornment')
			boxAdorn.Name = 'DarkVapeAuraBox'
			boxAdorn.AlwaysOnTop = true
			boxAdorn.Size = Vector3.new(3.2, 5.2, 3.2)
			boxAdorn.CFrame = CFrame.new(0, -0.2, 0)
			boxAdorn.ZIndex = 2
			boxAdorn.Transparency = 0.55
			boxAdorn.Adornee = nil
			boxAdorn.Visible = false
			boxAdorn.Parent = parentContainer
		end)

		pcall(function()
			auraRingAdorn = Instance.new('CylinderHandleAdornment')
			auraRingAdorn.Name = 'DarkVapeAuraRing'
			auraRingAdorn.AlwaysOnTop = false
			auraRingAdorn.Height = 0.08
			auraRingAdorn.Radius = Range and Range.Value or 20
			auraRingAdorn.InnerRadius = math.max(0.5, (Range and Range.Value or 20) - 0.22)
			auraRingAdorn.Color3 = Color3.fromRGB(168, 112, 248)
			auraRingAdorn.Transparency = 0.45
			auraRingAdorn.ZIndex = 1
			auraRingAdorn.Adornee = nil
			auraRingAdorn.Visible = false
			auraRingAdorn.Parent = parentContainer
		end)

		createProfileGui()

		Killaura:Clean(function()
			pcall(function() if highlight then highlight.Adornee = nil; highlight:Destroy() end end)
			pcall(function() if boxAdorn then boxAdorn.Adornee = nil; boxAdorn:Destroy() end end)
			pcall(function() if auraRingAdorn then auraRingAdorn.Adornee = nil; auraRingAdorn:Destroy() end end)
			pcall(function() if profileGui then profileGui:Destroy() end end)
			highlight = nil
			boxAdorn = nil
			auraRingAdorn = nil
			profileGui = nil
			profileFrame = nil
		end)

		Killaura:Clean(runService.Heartbeat:Connect(function()
			if not Killaura.Enabled then return end
			local ok, err = xpcall(step, debug.traceback)
			if not ok then
				vape.ModuleErrors = vape.ModuleErrors or {}
				vape.ModuleErrors.Killaura = tostring(err)
				warn('[DarkVape/Killaura] '..tostring(err))
				task.spawn(function()
					if Killaura.Enabled then Killaura:Toggle() end
					vape:CreateNotification('DarkVape', 'Killaura stopped after an error. Check the console.', 8, 'alert')
				end)
			end
		end))
	end,
	Tooltip = 'Automatically attacks nearby enemies using the Lutosys SwordHit payload with side profile preview & target visuals.'
})

