	loadstring(readfile('darkvape/games/'..vape.Place..'.lua'), 'bedwars')()
else
	if not shared.VapeDeveloper then
		local success, result = pcall(downloadFile, 'darkvape/games/'..vape.Place..'.lua')
		if success and result then
			loadstring(result, 'bedwars')()
		end
	end
end]=])
